# pass-cli inject template — secret NAME map (contains NO secret values).
# Format: a marker line "<<<ENV_VAR_NAME", then a pass:// vault/item/field ref
# in double braces on the next line. Do NOT put brace-refs in comments -- they
# are resolved too!
# Values are parsed as data (never eval'd) by .zsh-secrets.zsh.
<<<OPENCODE_ZEN_API_KEY
{{ pass://Personal/OPENCODE_ZEN_API_KEY/note }}
<<<TAVILY_API_KEY
{{ pass://Personal/TAVILY_API_KEY/note }}
<<<OPENROUTER_API_KEY
{{ pass://Personal/OPENROUTER_API_KEY/note }}
<<<MINIMAX_API_KEY
{{ pass://Personal/MINIMAX_API_KEY/note }}
<<<ZAI_API_KEY
{{ pass://Personal/ZAI_API_KEY/note }}
<<<QWENCLOUD_TOKEN_PLAN_API_KEY
{{ pass://Personal/QWENCLOUD_TOKEN_PLAN_API_KEY/note }}
<<<HERMES_SUDO_PWD
{{ pass://Personal/HERMES_SUDO_PWD/pwd }}
<<<PREVIEW_SUDO_PWD
{{ pass://Personal/PREVIEW_SUDO_PWD/pwd }}
<<<ADV_PROD_MYSQL_URI
{{ pass://Personal/ADV_PROD_MYSQL_URI/note }}
